;ФёклаFK_SM=-FK_+PL        DW FK0+SM,FK1+SM,FK2+SM,FK3+SM,FK4+SM        DW FK5+SM,FK6+SM,FK7+SM,FK8+SM,FK9+SMFK0     DB "Возьми, красавица!",SOBES        DB "Спасибо, мне это не нужно.",ENDFK1     DB "Здравствуй, девушка!",SOBES        DB "Здравствуйте, бабушка!",HERO        DB "Как тебя зовут, красавица?",SOBES        DB "Я Фёкла Девурдалак, борюсь с",CR        DB "нечистью. Хобби у меня такое. А",CR        DB "как вас зовут?",HERO        DB "Меня зовут Вера. И хобби у меня",CR        DB "примерно того же толка.",DIALOG,5FK2     DB "Фёкла, ты не поможешь разобраться",CR        DB "с летучими тварями на кладбище?",SOBES        DB "Летучие? Это, наверное, вампиры.",CR        DB "Они не из наших краев. Мало кто",CR        DB "про них знает... Разве что"        DB NEXT        DB "заморские мудрецы про них что-то",CR        DB "могут сказать. Вот только нету их",CR        DB "тут ни одного...",HERO        DB "Ха! Чтобы чужими знаниями",CR        DB "пользоваться, мудрецы не нужны.",CR        DB "Знания-то по-разному передаются!",SCRPT,37FK3     DB "Держи, вот книга... Только больно",CR        DB "мудрёная. Я думала проще будет...",SOBES        DB "Сейчас почитаем... Наверное здесь",CR        DB "какой-то шифр: ",34,"Тефебефе",CR        DB "пофомофожефет чефеснофок",34,"..."        DB NEXT        DB "Гммм ",34,"Чефеснофок",34,"... Наречие явно",CR        DB "древнеатлантское.",HERO        DB "И что это значит?",SOBES        DB "Это значит - ",34,"чеснок",34,". Не знаю,",CR        DB "причем он здесь? Ну да ладно,",CR        DB "возьми, авось чего придумаешь...",SCRPT,40FK4     DB "Охохох... Что же делать...",SOBES        DB "Ой, у меня после той мудрёной",CR        DB "загадки голова болит...",DIALOG,5FK5     DB "Как твои дела?",SOBES        DB "Нормально.",ENDFK6     DB "Ты не знаешь, что такого сделать,",CR        DB "чтобы чары Зловета на меня не",CR        DB "действовали?",SOBES        DB 34,"Глаз не видит, сердце не болит,",CR        DB "рука не тянется",34," - Николай",CR        DB "Степанович Ванхельсинг."        DB NEXT        DB "Был, помнится, большим любителем",CR        DB "волчьих ягод и сушеных тараканов.",CR        DB "Что он с ними делал, не знаю, но"        DB NEXT        DB "за девками был охоч подглядывать.",SCRPT,47FK7     DB "Фёкла, почему со мной никто не",CR        DB "разговаривает?",SOBES        DB "Ванхельсинг? Ты опять за мной",CR        DB "подглядываешь?! А ну пошел прочь!",END;           123456789-123456789-123456789-123FK8     DB "Тебе это нужно?",SOBES        DB "Спасибо! Давно хочу себе",CR        DB "накладные ногти справить! Возьми",CR        DB "эти зубы и отдай Хевору, а то ему"        DB NEXT        DB "жевать нечем.",SCRPT,63FK9     DB "Фёкла, забери у меня всё, только",CR        DB "помоги мне!",SOBES        DB "Степаныч, поди прочь!",ENDFEND